ons");Assert(!RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Output boundary bypasses stale allowed cache");UnityEngine.Time.realtimeSinceStartup=1;Assert(!RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack),"Cache expires");RebirthCapabilityService.Allowed=true;stack.StartingEntityId=29;Assert(!RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Client must not use viewer capability for another crafter");clientWorld.Remote=false;var crafter=new EntityPlayer{entityId=29,world=clientWorld};clientWorld.Owner=crafter;Assert(RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true)&&object.ReferenceEquals(RebirthCapabilityService.Last,crafter),"Host evaluates actual crafter");clientWorld.Owner=null;Assert(!RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Missing crafter holds open output");stack.recipe.Cooking=true;Assert(RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Existing cooking route retained");stack.windowGroup.Controller=new object();Assert(RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Personal queue untouched");
RebirthWorldCharacterRepository.IsServerAuthority=true;RebirthCapabilityService.Allowed=true;job.Recipe.Unresolved=true;Assert(!RebirthRecipeCapabilityIntegration.AuthorizeActiveQueue(w),"Unresolved definition holds authoritative queue");Intact(w,job);job.Recipe.Unresolved=false;Assert(RebirthRecipeCapabilityIntegration.AuthorizeActiveQueue(w),"Resolved definition resumes through owner capability");stack.windowGroup.Controller=new XUiC_WorkstationWindowGroup();stack.recipe.Unresolved=true;Assert(!RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack),"Unresolved definition bypasses allowed UI cache and cooking exemption");Assert(!RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Unresolved output held");job.Recipe.Marked=true;Assert(!RebirthRecipeCapabilityIntegration.AuthorizeActiveQueue(w),"Aggregate marked job cannot run multiplier3");Intact(w,job);job.Recipe.Marked=false;stack.recipe.Unresolved=false;stack.recipe.Marked=true;stack.recipeCount=2;Assert(!RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Aggregate open output cannot multiply paid payload");stack.recipeCount=1;Assert(RebirthRecipeCapabilityIntegration.AuthorizeOpenQueue(stack,true),"Valid aggregate multiplier returns to existing cooking/capability path");Console.WriteLine("PASS actual active/open queue gate: unavailable owner and denied capability preserve paid job/time/multiplier without cycle/save; repeated hold quiet, recovered capability resumes; existing cooking/client paths unchanged");}}